LogicalTypeAnnotation getLogicalTypeAnnotation(ConvertedType type, SchemaElement schemaElement) {
    switch (type) {
      case UTF8:
        return LogicalTypeAnnotation.stringType();
      case MAP:
        return LogicalTypeAnnotation.mapType();
      case MAP_KEY_VALUE:
        return LogicalTypeAnnotation.MapKeyValueTypeAnnotation.getInstance();
      case LIST:
        return LogicalTypeAnnotation.listType();
      case ENUM:
        return LogicalTypeAnnotation.enumType();
      case DECIMAL:
        int scale = (schemaElement == null ? 0 : schemaElement.scale);
        int precision = (schemaElement == null ? 0 : schemaElement.precision);
        return LogicalTypeAnnotation.decimalType(scale, precision);
      case DATE:
        return LogicalTypeAnnotation.dateType();
      case TIME_MILLIS:
        return LogicalTypeAnnotation.timeType(true, LogicalTypeAnnotation.TimeUnit.MILLIS);
      case TIME_MICROS:
        return LogicalTypeAnnotation.timeType(true, LogicalTypeAnnotation.TimeUnit.MICROS);
      case TIMESTAMP_MILLIS:
        return LogicalTypeAnnotation.timestampType(true, LogicalTypeAnnotation.TimeUnit.MILLIS);
      case TIMESTAMP_MICROS:
        return LogicalTypeAnnotation.timestampType(true, LogicalTypeAnnotation.TimeUnit.MICROS);
      case INTERVAL:
        return LogicalTypeAnnotation.IntervalLogicalTypeAnnotation.getInstance();
      case INT_8:
        return LogicalTypeAnnotation.intType(8, true);
      case INT_16:
        return LogicalTypeAnnotation.intType(16, true);
      case INT_32:
        return LogicalTypeAnnotation.intType(32, true);
      case INT_64:
        return LogicalTypeAnnotation.intType(64, true);
      case UINT_8:
        return LogicalTypeAnnotation.intType(8, false);
      case UINT_16:
        return LogicalTypeAnnotation.intType(16, false);
      case UINT_32:
        return LogicalTypeAnnotation.intType(32, false);
      case UINT_64:
        return LogicalTypeAnnotation.intType(64, false);
      case JSON:
        return LogicalTypeAnnotation.jsonType();
      case BSON:
        return LogicalTypeAnnotation.bsonType();
      default:
        throw new RuntimeException(
            "Can't convert converted type to logical type, unknown converted type " + type);
    }
  }

LogicalTypeAnnotation getLogicalTypeAnnotation(LogicalType type) {
    LogicalType._Fields setField = type.getSetField();
    if (setField == null) {
      // Ignore unknown logical types to preserve the physical type.
      return null;
    }
    switch (setField) {
      case MAP:
        return LogicalTypeAnnotation.mapType();
      case BSON:
        return LogicalTypeAnnotation.bsonType();
      case DATE:
        return LogicalTypeAnnotation.dateType();
      case ENUM:
        return LogicalTypeAnnotation.enumType();
      case JSON:
        return LogicalTypeAnnotation.jsonType();
      case LIST:
        return LogicalTypeAnnotation.listType();
      case TIME:
        TimeType time = type.getTIME();
        return LogicalTypeAnnotation.timeType(time.isAdjustedToUTC, convertTimeUnit(time.unit));
      case STRING:
        return LogicalTypeAnnotation.stringType();
      case DECIMAL:
        DecimalType decimal = type.getDECIMAL();
        return LogicalTypeAnnotation.decimalType(decimal.scale, decimal.precision);
      case INTEGER:
        IntType integer = type.getINTEGER();
        return LogicalTypeAnnotation.intType(integer.bitWidth, integer.isSigned);
      case UNKNOWN:
        return LogicalTypeAnnotation.unknownType();
      case TIMESTAMP:
        TimestampType timestamp = type.getTIMESTAMP();
        return LogicalTypeAnnotation.timestampType(timestamp.isAdjustedToUTC, convertTimeUnit(timestamp.unit));
      case UUID:
        return LogicalTypeAnnotation.uuidType();
      case FLOAT16:
        return LogicalTypeAnnotation.float16Type();
      case GEOMETRY:
        GeometryType geometry = type.getGEOMETRY();
        return LogicalTypeAnnotation.geometryType(geometry.getCrs());
      case GEOGRAPHY:
        GeographyType geography = type.getGEOGRAPHY();
        return LogicalTypeAnnotation.geographyType(
            geography.getCrs(), toParquetEdgeInterpolationAlgorithm(geography.getAlgorithm()));
      case VARIANT:
        VariantType variant = type.getVARIANT();
        return LogicalTypeAnnotation.variantType(variant.getSpecification_version());
      case FILE:
        // Present in the format but not mapped to a LogicalTypeAnnotation yet. Ignore it to
        // preserve the physical type, as an unrecognised logical type would be.
        return null;
      default:
        throw new RuntimeException("Unknown logical type " + type);
    }
  }

public ParquetMetadata fromParquetMetadata(
      FileMetaData parquetMetadata,
      InternalFileDecryptor fileDecryptor,
      boolean encryptedFooter,
      Map<RowGroup, Long> rowGroupToRowIndexOffsetMap)
      throws IOException {
    MessageType messageType = fromParquetSchema(parquetMetadata.getSchema(), parquetMetadata.getColumn_orders());
    org.apache.parquet.hadoop.metadata.FileMetaData fileMetaData =
        buildFileMetaData(parquetMetadata, messageType, encryptedFooter, fileDecryptor);
    String createdBy = fileMetaData.getCreatedBy();
    ParsedVersion writerVersion = null;
    try {
      writerVersion = fileMetaData.getWriterVersion();
    } catch (VersionParseException e) {
      // Fall back to String-based path which logs the parse error with full context
    }
    List<BlockMetaData> blocks = new ArrayList<BlockMetaData>();
    List<RowGroup> row_groups = parquetMetadata.getRow_groups();

    if (row_groups != null) {
      for (RowGroup rowGroup : row_groups) {
        BlockMetaData blockMetaData = new BlockMetaData();
        blockMetaData.setRowCount(rowGroup.getNum_rows());
        blockMetaData.setTotalByteSize(rowGroup.getTotal_byte_size());
        if (rowGroupToRowIndexOffsetMap.containsKey(rowGroup)) {
          blockMetaData.setRowIndexOffset(rowGroupToRowIndexOffsetMap.get(rowGroup));
        }
        // not set in legacy files
        if (rowGroup.isSetOrdinal()) {
          blockMetaData.setOrdinal(rowGroup.getOrdinal());
        }
        List<ColumnChunk> columns = rowGroup.getColumns();
        String filePath = columns.get(0).getFile_path();
        int columnOrdinal = -1;
        for (ColumnChunk columnChunk : columns) {
          columnOrdinal++;
          if ((filePath == null && columnChunk.getFile_path() != null)
              || (filePath != null && !filePath.equals(columnChunk.getFile_path()))) {
            throw new ParquetDecodingException(
                "all column chunks of the same row group must be in the same file for now");
          }
          ColumnMetaData metaData = columnChunk.meta_data;
          ColumnCryptoMetaData cryptoMetaData = columnChunk.getCrypto_metadata();
          ColumnChunkMetaData column = null;
          ColumnPath columnPath = null;
          boolean lazyMetadataDecryption = false;

          if (null == cryptoMetaData) { // Plaintext column
            columnPath = getPath(metaData);
            if (null != fileDecryptor && !fileDecryptor.plaintextFile()) {
              // mark this column as plaintext in encrypted file decryptor
              fileDecryptor.setColumnCryptoMetadata(
                  columnPath, false, false, (byte[]) null, columnOrdinal);
            }
          } else { // Encrypted column
            boolean encryptedWithFooterKey = cryptoMetaData.isSetENCRYPTION_WITH_FOOTER_KEY();
            if (encryptedWithFooterKey) { // Column encrypted with footer key
              if (null == fileDecryptor) {
                throw new ParquetCryptoRuntimeException(
                    "Column encrypted with footer key: No keys available");
              }
              if (null == metaData) {
                throw new ParquetCryptoRuntimeException(
                    "ColumnMetaData not set in Encryption with Footer key");
              }
              columnPath = getPath(metaData);
              if (!encryptedFooter) { // Unencrypted footer. Decrypt full column metadata, using footer
                // key
                ByteArrayInputStream tempInputStream =
                    new ByteArrayInputStream(columnChunk.getEncrypted_column_metadata());
                byte[] columnMetaDataAAD = AesCipher.createModuleAAD(
                    fileDecryptor.getFileAAD(),
                    ModuleType.ColumnMetaData,
                    rowGroup.getOrdinal(),
                    columnOrdinal,
                    -1);
                try {
                  metaData = readColumnMetaData(
                      tempInputStream, fileDecryptor.fetchFooterDecryptor(), columnMetaDataAAD);
                } catch (IOException e) {
                  throw new ParquetCryptoRuntimeException(
                      columnPath + ". Failed to decrypt column metadata", e);
                }
              }
              fileDecryptor.setColumnCryptoMetadata(columnPath, true, true, (byte[]) null, columnOrdinal);
            } else { // Column encrypted with column key
              // setColumnCryptoMetadata triggers KMS interaction, hence delayed until this column is
              // projected
              lazyMetadataDecryption = true;
            }
          }

          if (!lazyMetadataDecryption) { // full column metadata (with stats) is available
            PrimitiveType primitiveType =
                messageType.getType(columnPath.toArray()).asPrimitiveType();
            column =
                buildColumnChunkMetaData(metaData, columnPath, primitiveType, writerVersion, createdBy);
            column.setRowGroupOrdinal(rowGroup.getOrdinal());
            if (metaData.isSetBloom_filter_offset()) {
              column.setBloomFilterOffset(metaData.getBloom_filter_offset());
            }
            if (metaData.isSetBloom_filter_length()) {
              column.setBloomFilterLength(metaData.getBloom_filter_length());
            }
          } else { // column encrypted with column key
            // Metadata will be decrypted later, if this column is accessed
            EncryptionWithColumnKey columnKeyStruct = cryptoMetaData.getENCRYPTION_WITH_COLUMN_KEY();
            List<String> pathList = columnKeyStruct.getPath_in_schema();
            byte[] columnKeyMetadata = columnKeyStruct.getKey_metadata();
            columnPath = ColumnPath.get(pathList.toArray(new String[pathList.size()]));
            byte[] encryptedMetadataBuffer = columnChunk.getEncrypted_column_metadata();
            column = ColumnChunkMetaData.getWithEncryptedMetadata(
                this,
                columnPath,
                messageType.getType(columnPath.toArray()).asPrimitiveType(),
                encryptedMetadataBuffer,
                columnKeyMetadata,
                fileDecryptor,
                rowGroup.getOrdinal(),
                columnOrdinal,
                createdBy);
          }

          column.setColumnIndexReference(toColumnIndexReference(columnChunk));
          column.setOffsetIndexReference(toOffsetIndexReference(columnChunk));

          // TODO
          // index_page_offset
          // key_value_metadata
          blockMetaData.addColumn(column);
        }
        blockMetaData.setPath(filePath);
        blocks.add(blockMetaData);
      }
    }
    return new ParquetMetadata(fileMetaData, blocks);
  }

protected Converter newScalarConverter(
      ParentValueContainer pvc,
      Message.Builder parentBuilder,
      Descriptors.FieldDescriptor fieldDescriptor,
      Type parquetType) {

    JavaType javaType = fieldDescriptor.getJavaType();

    switch (javaType) {
      case STRING:
        return new ProtoStringConverter(pvc);
      case FLOAT:
        return new ProtoFloatConverter(pvc);
      case DOUBLE:
        return new ProtoDoubleConverter(pvc);
      case BOOLEAN:
        return new ProtoBooleanConverter(pvc);
      case BYTE_STRING:
        return new ProtoBinaryConverter(pvc);
      case ENUM:
        return new ProtoEnumConverter(pvc, fieldDescriptor);
      case INT:
        return new ProtoIntConverter(pvc);
      case LONG:
        return new ProtoLongConverter(pvc);
      case MESSAGE: {
        if (parquetType.isPrimitive()) {
          // if source is a Primitive type yet target is MESSAGE, it's probably a wrapped message
          Descriptor messageType = fieldDescriptor.getMessageType();
          if (messageType.equals(DoubleValue.getDescriptor())) {
            return new ProtoDoubleValueConverter(pvc);
          }
          if (messageType.equals(FloatValue.getDescriptor())) {
            return new ProtoFloatValueConverter(pvc);
          }
          if (messageType.equals(Int64Value.getDescriptor())) {
            return new ProtoInt64ValueConverter(pvc);
          }
          if (messageType.equals(UInt64Value.getDescriptor())) {
            return new ProtoUInt64ValueConverter(pvc);
          }
          if (messageType.equals(Int32Value.getDescriptor())) {
            return new ProtoInt32ValueConverter(pvc);
          }
          if (messageType.equals(UInt32Value.getDescriptor())) {
            return new ProtoUInt32ValueConverter(pvc);
          }
          if (messageType.equals(BoolValue.getDescriptor())) {
            return new ProtoBoolValueConverter(pvc);
          }
          if (messageType.equals(StringValue.getDescriptor())) {
            return new ProtoStringValueConverter(pvc);
          }
          if (messageType.equals(BytesValue.getDescriptor())) {
            return new ProtoBytesValueConverter(pvc);
          }
          // Otherwise the column holds the serialized message itself: ProtoSchemaConverter stores
          // fields of empty message types and recursion beyond maxRecursion as proto bytes.
          return new ProtoBinaryMessageConverter(pvc, parentBuilder, fieldDescriptor);
        }
        Message.Builder subBuilder = parentBuilder.newBuilderForField(fieldDescriptor);
        return new ProtoMessageConverter(conf, pvc, subBuilder, parquetType.asGroupType(), extraMetadata);
      }
    }

    throw new UnsupportedOperationException(
        String.format("Cannot convert type: %s" + " (Parquet type: %s) ", javaType, parquetType));
  }

