public void endObject() {
    if (objectBuilder == null) {
      throw new IllegalStateException("Cannot call endObject() without calling startObject() first.");
    }
    ArrayList<FieldEntry> fields = objectBuilder.validateAndGetFields();
    int numFields = fields.size();
    Collections.sort(fields);
    int maxId = numFields == 0 ? 0 : fields.get(0).id;

    int distinctPos = 0;
    // Maintain a list of distinct keys in-place.
    for (int i = 1; i < numFields; ++i) {
      maxId = Math.max(maxId, fields.get(i).id);
      if (fields.get(i).id == fields.get(i - 1).id) {
        // Found a duplicate key. Keep the field with the greater offset, because it was written last.
        if (fields.get(distinctPos).offset < fields.get(i).offset) {
          fields.set(distinctPos, fields.get(i));
        }
      } else {
        // Found a distinct key. Add the field to the list.
        distinctPos++;
        fields.set(distinctPos, fields.get(i));
      }
    }

    if (distinctPos + 1 < fields.size()) {
      numFields = distinctPos + 1;
      // Resize `fields` to `size`.
      fields.subList(numFields, fields.size()).clear();
    }

    // Compute the data size from the retained fields. This must happen after deduplication, since a
    // duplicate key keeps the last-written value, whose size may differ from the first occurrence.
    int dataSize = 0;
    for (int i = 0; i < numFields; ++i) {
      dataSize += fields.get(i).valueSize;
    }

    boolean largeSize = numFields > VariantUtil.U8_MAX;
    int sizeBytes = largeSize ? VariantUtil.U32_SIZE : 1;
    int idSize = getMinIntegerSize(maxId);
    int offsetSize = getMinIntegerSize(dataSize);
    // The data starts after: the header byte, object size, id list, and offset list.
    int dataOffset = 1 + sizeBytes + numFields * idSize + (numFields + 1) * offsetSize;
    checkCapacity(dataOffset + dataSize);

    // Write the header byte and size entry.
    writeBuffer[writePos] = VariantUtil.objectHeader(largeSize, idSize, offsetSize);
    VariantUtil.writeLong(writeBuffer, writePos + 1, numFields, sizeBytes);

    int idStart = writePos + 1 + sizeBytes;
    int offsetStart = idStart + numFields * idSize;
    int currOffset = 0;

    // Loop over all fields and write the key id, offset, and data to the appropriate offsets
    for (int i = 0; i < numFields; ++i) {
      FieldEntry field = fields.get(i);
      VariantUtil.writeLong(writeBuffer, idStart + i * idSize, field.id, idSize);
      VariantUtil.writeLong(writeBuffer, offsetStart + i * offsetSize, currOffset, offsetSize);
      System.arraycopy(
          objectBuilder.writeBuffer,
          field.offset,
          writeBuffer,
          writePos + dataOffset + currOffset,
          field.valueSize);
      currOffset += field.valueSize;
    }
    VariantUtil.writeLong(writeBuffer, offsetStart + numFields * offsetSize, dataSize, offsetSize);
    writePos += dataOffset + dataSize;
    this.objectBuilder = null;
  }

static Converter newScalarConverter(PrimitiveType primitive, ParentConverter<VariantBuilder> parent) {
    ShreddedScalarConverter typedConverter = null;
    LogicalTypeAnnotation annotation = primitive.getLogicalTypeAnnotation();
    PrimitiveType.PrimitiveTypeName primitiveType = primitive.getPrimitiveTypeName();
    if (primitiveType == BOOLEAN) {
      typedConverter = new VariantBooleanConverter(parent);
    } else if (annotation instanceof LogicalTypeAnnotation.IntLogicalTypeAnnotation) {
      LogicalTypeAnnotation.IntLogicalTypeAnnotation intAnnotation =
          (LogicalTypeAnnotation.IntLogicalTypeAnnotation) annotation;
      if (!intAnnotation.isSigned()) {
        throw new UnsupportedOperationException("Unsupported shredded value type: " + intAnnotation);
      }
      int width = intAnnotation.getBitWidth();
      if (width == 8) {
        typedConverter = new VariantByteConverter(parent);
      } else if (width == 16) {
        typedConverter = new VariantShortConverter(parent);
      } else if (width == 32) {
        typedConverter = new VariantIntConverter(parent);
      } else if (width == 64) {
        typedConverter = new VariantLongConverter(parent);
      } else {
        throw new UnsupportedOperationException("Unsupported shredded value type: " + intAnnotation);
      }
    } else if (annotation == null && primitiveType == INT32) {
      typedConverter = new VariantIntConverter(parent);
    } else if (annotation == null && primitiveType == INT64) {
      typedConverter = new VariantLongConverter(parent);
    } else if (primitiveType == FLOAT) {
      typedConverter = new VariantFloatConverter(parent);
    } else if (primitiveType == DOUBLE) {
      typedConverter = new VariantDoubleConverter(parent);
    } else if (annotation instanceof LogicalTypeAnnotation.DecimalLogicalTypeAnnotation) {
      LogicalTypeAnnotation.DecimalLogicalTypeAnnotation decimalType =
          (LogicalTypeAnnotation.DecimalLogicalTypeAnnotation) annotation;
      typedConverter = new VariantDecimalConverter(parent, decimalType.getScale());
    } else if (annotation instanceof LogicalTypeAnnotation.DateLogicalTypeAnnotation) {
      typedConverter = new VariantDateConverter(parent);
    } else if (annotation instanceof LogicalTypeAnnotation.TimestampLogicalTypeAnnotation) {
      LogicalTypeAnnotation.TimestampLogicalTypeAnnotation timestampType =
          (LogicalTypeAnnotation.TimestampLogicalTypeAnnotation) annotation;
      if (timestampType.isAdjustedToUTC()) {
        switch (timestampType.getUnit()) {
          case MILLIS:
            throw new UnsupportedOperationException("MILLIS not supported by Variant");
          case MICROS:
            typedConverter = new VariantTimestampConverter(parent);
            break;
          case NANOS:
            typedConverter = new VariantTimestampNanosConverter(parent);
            break;
        }
      } else {
        switch (timestampType.getUnit()) {
          case MILLIS:
            throw new UnsupportedOperationException("MILLIS not supported by Variant");
          case MICROS:
            typedConverter = new VariantTimestampNtzConverter(parent);
            break;
          case NANOS:
            typedConverter = new VariantTimestampNanosNtzConverter(parent);
            break;
        }
      }
    } else if (annotation instanceof LogicalTypeAnnotation.TimeLogicalTypeAnnotation) {
      LogicalTypeAnnotation.TimeLogicalTypeAnnotation timeType =
          (LogicalTypeAnnotation.TimeLogicalTypeAnnotation) annotation;
      if (timeType.isAdjustedToUTC() || timeType.getUnit() != MICROS) {
        throw new UnsupportedOperationException(timeType + " not supported by Variant");
      } else {
        typedConverter = new VariantTimeConverter(parent);
      }
    } else if (annotation instanceof LogicalTypeAnnotation.UUIDLogicalTypeAnnotation) {
      typedConverter = new VariantUUIDConverter(parent);
    } else if (annotation instanceof LogicalTypeAnnotation.StringLogicalTypeAnnotation) {
      typedConverter = new VariantStringConverter(parent);
    } else if (primitiveType == BINARY) {
      typedConverter = new VariantBinaryConverter(parent);
    } else {
      throw new UnsupportedOperationException("Unsupported shredded value type: " + primitive);
    }
    return typedConverter;
  }

static Variant.Type getType(ByteBuffer value) {
    checkIndex(value.position(), value.limit());
    int basicType = value.get(value.position()) & BASIC_TYPE_MASK;
    int typeInfo = (value.get(value.position()) >> BASIC_TYPE_BITS) & PRIMITIVE_TYPE_MASK;
    switch (basicType) {
      case SHORT_STR:
        return Variant.Type.STRING;
      case OBJECT:
        return Variant.Type.OBJECT;
      case ARRAY:
        return Variant.Type.ARRAY;
      default:
        switch (typeInfo) {
          case NULL:
            return Variant.Type.NULL;
          case TRUE:
          case FALSE:
            return Variant.Type.BOOLEAN;
          case INT8:
            return Variant.Type.BYTE;
          case INT16:
            return Variant.Type.SHORT;
          case INT32:
            return Variant.Type.INT;
          case INT64:
            return Variant.Type.LONG;
          case DOUBLE:
            return Variant.Type.DOUBLE;
          case DECIMAL4:
            return Variant.Type.DECIMAL4;
          case DECIMAL8:
            return Variant.Type.DECIMAL8;
          case DECIMAL16:
            return Variant.Type.DECIMAL16;
          case DATE:
            return Variant.Type.DATE;
          case TIMESTAMP_TZ:
            return Variant.Type.TIMESTAMP_TZ;
          case TIMESTAMP_NTZ:
            return Variant.Type.TIMESTAMP_NTZ;
          case FLOAT:
            return Variant.Type.FLOAT;
          case BINARY:
            return Variant.Type.BINARY;
          case LONG_STR:
            return Variant.Type.STRING;
          case TIME:
            return Variant.Type.TIME;
          case TIMESTAMP_NANOS_TZ:
            return Variant.Type.TIMESTAMP_NANOS_TZ;
          case TIMESTAMP_NANOS_NTZ:
            return Variant.Type.TIMESTAMP_NANOS_NTZ;
          case UUID:
            return Variant.Type.UUID;
          default:
            throw new UnsupportedOperationException(
                String.format("Unknown type in Variant. primitive type: %d", typeInfo));
        }
    }
  }

static long getLong(ByteBuffer value) {
    checkIndex(value.position(), value.limit());
    int basicType = value.get(value.position()) & BASIC_TYPE_MASK;
    int typeInfo = (value.get(value.position()) >> BASIC_TYPE_BITS) & PRIMITIVE_TYPE_MASK;
    if (basicType != PRIMITIVE) {
      throw unexpectedType(
          new Variant.Type[] {
            Variant.Type.BYTE,
            Variant.Type.SHORT,
            Variant.Type.INT,
            Variant.Type.DATE,
            Variant.Type.LONG,
            Variant.Type.TIMESTAMP_TZ,
            Variant.Type.TIMESTAMP_NTZ,
            Variant.Type.TIME,
            Variant.Type.TIMESTAMP_NANOS_TZ,
            Variant.Type.TIMESTAMP_NANOS_NTZ
          },
          value);
    }
    switch (typeInfo) {
      case INT8:
        return readLong(value, value.position() + 1, 1);
      case INT16:
        return readLong(value, value.position() + 1, 2);
      case INT32:
      case DATE:
        return readLong(value, value.position() + 1, 4);
      case INT64:
      case TIMESTAMP_TZ:
      case TIMESTAMP_NTZ:
      case TIME:
      case TIMESTAMP_NANOS_TZ:
      case TIMESTAMP_NANOS_NTZ:
        return readLong(value, value.position() + 1, 8);
      default:
        throw unexpectedType(
            new Variant.Type[] {
              Variant.Type.BYTE,
              Variant.Type.SHORT,
              Variant.Type.INT,
              Variant.Type.DATE,
              Variant.Type.LONG,
              Variant.Type.TIMESTAMP_TZ,
              Variant.Type.TIMESTAMP_NTZ,
              Variant.Type.TIME,
              Variant.Type.TIMESTAMP_NANOS_TZ,
              Variant.Type.TIMESTAMP_NANOS_NTZ
            },
            value);
    }
  }

public static int valueSize(ByteBuffer value) {
    int pos = value.position();
    int basicType = value.get(pos) & BASIC_TYPE_MASK;
    switch (basicType) {
      case SHORT_STR:
        int stringSize = (value.get(pos) >> BASIC_TYPE_BITS) & PRIMITIVE_TYPE_MASK;
        return 1 + stringSize;
      case OBJECT: {
        VariantUtil.ObjectInfo info = VariantUtil.getObjectInfo(slice(value, pos));
        return info.dataStartOffset
            + readUnsigned(
                value,
                pos + info.offsetStartOffset + info.numElements * info.offsetSize,
                info.offsetSize);
      }
      case ARRAY: {
        VariantUtil.ArrayInfo info = VariantUtil.getArrayInfo(slice(value, pos));
        return info.dataStartOffset
            + readUnsigned(
                value,
                pos + info.offsetStartOffset + info.numElements * info.offsetSize,
                info.offsetSize);
      }
      default: {
        int typeInfo = (value.get(pos) >> BASIC_TYPE_BITS) & PRIMITIVE_TYPE_MASK;
        switch (typeInfo) {
          case NULL:
          case TRUE:
          case FALSE:
            return 1;
          case INT8:
            return 2;
          case INT16:
            return 3;
          case INT32:
          case DATE:
          case FLOAT:
            return 5;
          case INT64:
          case DOUBLE:
          case TIMESTAMP_TZ:
          case TIMESTAMP_NTZ:
          case TIME:
          case TIMESTAMP_NANOS_TZ:
          case TIMESTAMP_NANOS_NTZ:
            return 9;
          case DECIMAL4:
            return 6;
          case DECIMAL8:
            return 10;
          case DECIMAL16:
            return 18;
          case BINARY:
          case LONG_STR:
            return 1 + U32_SIZE + readUnsigned(value, pos + 1, U32_SIZE);
          case UUID:
            return 1 + UUID_SIZE;
          default:
            throw new UnsupportedOperationException(
                String.format("Unknown type in Variant. primitive type: %d", typeInfo));
        }
      }
    }
  }
